from __future__ import annotations

import sys
from pathlib import Path

def _find_repo_root() -> Path:
    here = Path(__file__).resolve()
    for p in [here, *here.parents]:
        if (p / "src" / "cfnlint").is_dir():
            return p
    raise RuntimeError("Could not locate cfnlint source tree (expected .../src/cfnlint).")

_REPO_ROOT = _find_repo_root()
_SRC = _REPO_ROOT / "src"
if str(_SRC) not in sys.path:
    sys.path.insert(0, str(_SRC))

from cfnlint.template import Template
from cfnlint.template.transforms._language_extensions import _Transform

def _make_cfn(extra: dict) -> Template:
    template = {
        "Transform": ["AWS::LanguageExtensions"],
        "Mappings": {
            "Sizes": {
                "small": {"cpu": "256", "mem": "512"},
                "large": {"cpu": "1024", "mem": "2048"},
            }
        },
        "Parameters": {
            "Env": {
                "Type": "String",
                "AllowedValues": ["dev", "prod"],
                "Default": "dev",
            },
        },
        "Resources": {},
    }
    template.update(extra)
    return Template("", template)

class TestLanguageExtensionsWalkDefUsePairsQA:
    def test_language_extensions_walk_def_use_pairs_case(self):
        cfn_a = _make_cfn(
            {
                "Resources": {
                    "Fn::ForEach::EnvLoop": [
                        "Env",
                        ["dev", "prod"],
                        {
                            "Bucket${Env}": {
                                "Type": "AWS::S3::Bucket",
                                "Properties": {
                                    "BucketName": {"Fn::Sub": "${Env}-bucket"},
                                },
                            }
                        },
                    ]
                }
            }
        )
        errors, out = _Transform().transform(cfn_a)
        assert errors == []
        assert "Bucketdev" in out["Resources"]
        assert "Bucketprod" in out["Resources"]

        cfn_b = _make_cfn(
            {"Resources": {"X": {"Properties": {"P": {"Fn::ToJsonString": {"a": 1}}}}}}
        )
        _, out = _Transform().transform(cfn_b)
        assert "Fn::ToJsonString" in out["Resources"]["X"]["Properties"]["P"]

        cfn_c = _make_cfn(
            {
                "Resources": {
                    "X": {
                        "Properties": {
                            "ListForm": {"Fn::GetAtt": ["Resource1", "Arn"]},
                            "StrForm": {"Fn::GetAtt": "Resource1.Arn"},
                        }
                    }
                }
            }
        )
        _, out = _Transform().transform(cfn_c)
        assert out["Resources"]["X"]["Properties"]["ListForm"] is not None

        cfn_d = _make_cfn(
            {"Resources": {"X": {"Properties": {"P": {"Fn::Sub": "literal"}}}}}
        )
        _, out = _Transform().transform(cfn_d)

        cfn_e = _make_cfn(
            {
                "Resources": {
                    "X": {
                        "Properties": {
                            "P": {
                                "Fn::Sub": [
                                    "${Custom}-suffix",
                                    {"Custom": "rendered"},
                                ]
                            }
                        }
                    }
                }
            }
        )
        _, out = _Transform().transform(cfn_e)

        cfn_f = _make_cfn(
            {
                "Resources": {
                    "X": {
                        "Properties": {
                            "Cpu": {"Fn::FindInMap": ["Sizes", "small", "cpu"]},
                        }
                    }
                }
            }
        )
        _, out = _Transform().transform(cfn_f)
        assert out["Resources"]["X"]["Properties"]["Cpu"] == "256"

        cfn_g = _make_cfn(
            {
                "Resources": {
                    "X": {
                        "Properties": {
                            "Cpu": {
                                "Fn::FindInMap": [
                                    "MissingMap",
                                    {"Ref": "Env"},
                                    "cpu",
                                ]
                            }
                        }
                    }
                }
            }
        )
        _, out = _Transform().transform(cfn_g)

        cfn_h = _make_cfn(
            {
                "Resources": {
                    "Fn::ForEach::EnvLoop": [
                        "Env",
                        ["alpha"],
                        {
                            "Q${Env}": {
                                "Type": "AWS::Custom",
                                "Properties": {
                                    "InParams": {"Ref": "Env"},
                                    "NotInParams": {"Ref": "AWS::Region"},
                                    "DictRef": {"Ref": {"Fn::Sub": "Env"}},
                                },
                            }
                        },
                    ],
                }
            }
        )
        _, out = _Transform().transform(cfn_h)

        cfn_i = _make_cfn(
            {
                "Outputs": {
                    "Items": [
                        "literal-1",
                        {"Ref": "Env"},
                        42,
                        None,
                        {"Fn::Sub": "${Env}-x"},
                    ],
                },
            }
        )
        _, out = _Transform().transform(cfn_i)

        cfn_j = _make_cfn(
            {
                "Outputs": {
                    "Foo": {"Drop": None, "Keep": "kept"},
                },
            }
        )
        _, out = _Transform().transform(cfn_j)
        assert out["Outputs"]["Foo"].get("Keep") == "kept"

    def __init__(self, message: str, key: Any) -> None:
        super().__init__(message)
        self.key = key


class _TypeError(Exception):
    def __init__(self, message: str, key: Any) -> None:
        super().__init__(message)
        self.key = key


def language_extension(cfn: Any) -> TransformResult:
    transform = _Transform()
    try:
        return transform.transform(cfn)
    except (_ValueError, _TypeError, _ResolveError) as e:
        LOGGER.debug(e, exc_info=True)
        # pylint: disable=import-outside-toplevel
        from cfnlint.match import Match  # pylint: disable=cyclic-import
        from cfnlint.rules.errors import TransformError  # pylint: disable=cyclic-import

        message = "Error transforming template: {0}"
        if hasattr(e.key, "start_mark"):
            sm_line = e.key.start_mark.line + 1
            sm_column = e.key.start_mark.column + 1
        else:
            sm_line = 1
            sm_column = 1
        if hasattr(e.key, "end_mark"):
            em_line = e.key.end_mark.line + 1
            em_column = e.key.end_mark.column + 1
        else:
            em_line = 1
            em_column = 1

        return [
            Match.create(
                linenumber=sm_line,
                columnnumber=sm_column,
                linenumberend=em_line,
                columnnumberend=em_column,
                filename=cfn.filename,
                rule=TransformError(),
                message=message.format(str(e)),
            )
        ], None
    except Exception as e:  # pylint: disable=broad-exception-caught
        LOGGER.debug(e, exc_info=True)
        # pylint: disable=import-outside-toplevel
        from cfnlint.match import Match  # pylint: disable=cyclic-import
        from cfnlint.rules.errors import TransformError  # pylint: disable=cyclic-import

        message = "Error transforming template: {0}"
        return [
            Match.create(
                filename=cfn.filename,
                rule=TransformError(),
                message=message.format(str(e)),
            )
        ], None


class _Transform:
    def __init__(self) -> None:
        self._collections: MutableMapping[str, str] = {}

    def transform(self, cfn: Any) -> TransformResult:
        """Transform the template"""
        return [], self._walk(cfn.template, {}, cfn)

    # pylint: disable=too-many-return-statements
    def _walk(self, item: Any, params: MutableMapping[str, Any], cfn: Any):
        obj = deepcopy(item)
        if isinstance(obj, dict):
            # adjust keys if needed
            if params:
                for k, v in item.items():
                    _, new_k = self._replace_string_params(k, params)
                    if new_k != k:
                        del obj[k]
                        obj[new_k] = v

            for k, v in deepcopy(obj).items():
                # see if key matches Fn::ForEach
                if re.match(FUNCTION_FOR_EACH, k):
                    # only translate the foreach if its valid
                    foreach = _ForEach(k, v, self._collections)
                    # get the values will flatten the foreach
                    for collection_value in foreach.items(cfn, params):
                        flattened = self._walk(
                            v[2], {**params, **{v[0]: collection_value}}, cfn
                        )
                        for f_k, f_v in flattened.items():
                            if f_k not in obj:
                                obj[f_k] = f_v
                            else:
                                raise _ValueError(
                                    f"Duplicate {f_k} while doing transformation",
                                    f_k,
                                )
                    del obj[k]
                elif k == "Fn::ToJsonString":
                    # extra special handing for this as {} could be a valid value
                    return obj
                elif k == "Fn::GetAtt":
                    if isinstance(v, (list, str)):
                        obj[k] = self._walk(v, params, cfn)
                elif k == "Fn::Sub":
                    if isinstance(v, str):
                        only_string, obj[k] = self._replace_string_params(v, params)
                        if only_string:
                            return obj[k]
                    if isinstance(v, list):
                        only_string, obj[k][0] = self._replace_string_params(
                            v[0],
                            params,
                        )
                        if only_string:
                            return obj[k][0]
                        if len(v) == 2:
                            obj[k][1] = self._walk(v[1], params, cfn)
                elif k == "Fn::FindInMap":
                    try:
                        mapping = _ForEachValueFnFindInMap(get_hash(v), v)
                        map_value = mapping.value(cfn, params, True, False)
                        # if we can resolve it we will return it
                        if isinstance(map_value, tuple([list]) + _SCALAR_TYPES):
                            return map_value
                    except Exception as e:  # pylint: disable=broad-exception-caught
                        # We couldn't resolve the FindInMap so we are going to
                        # leave it as it is
                        LOGGER.debug("Transform and Fn::FindInMap error: %s", {str(e)})
                    for i, el in enumerate(v):
                        v[i] = self._walk(el, params, cfn)
                    obj[k] = v
                elif k == "Ref":
                    if isinstance(v, str):
                        if v in params:
                            return params[v]
                    elif isinstance(v, dict):
                        r = self._walk(v, params, cfn)
                        if isinstance(r, str):
                            if r in params:
                                return params[r]
                        obj[k] = r
                else:
                    sub_value = self._walk(v, params, cfn)
                    # a sub object may be none or we have returned
                    # an empty object.  We don't want to remove empty
                    # strings "" or 0 (zeros)
                    # Remove `or sub_value == {}` for issue #2896
                    if sub_value is None:
                        del obj[k]
                    else:
                        obj[k] = sub_value
        elif isinstance(obj, list):
            for i, v in enumerate(obj):
                obj[i] = self._walk(v, params, cfn)
        return obj

    def _replace_string_params(
        self,
        s: str,
        params: Mapping[str, Any],
    ) -> Tuple[bool, str]:
        pattern = r"(\$|&){[a-zA-Z0-9\.:]+}"
        if not re.search(pattern, s):
            return (True, s)

        new_s = deepcopy(s)
        for k, v in params.items():
            if isinstance(v, dict):
                v = (
                    hashlib.md5(json.dumps(v).encode("utf-8"), usedforsecurity=False)
                    .digest()
                    .hex()[0:4]
                )
            new_s = re.sub(rf"\$\{{{k}\}}", v, new_s)
            new_s = re.sub(rf"\&\{{{k}\}}", re.sub("[^0-9a-zA-Z]+", "", v), new_s)

        if isinstance(s, str_node):
            new_s = str_node(new_s, s.start_mark, s.end_mark)

        return (not (bool(re.search(pattern, new_s))), new_s)


class _ForEachValue:
    def __init__(self, _hash: str, value: Any = None) -> None:
        if value:
            self._value = value

        self._hash = _hash

    @staticmethod
    def create(obj: Any) -> _ForEachValue:
        _hash = get_hash(obj)
        if isinstance(obj, _SCALAR_TYPES):
            return _ForEachValue(_hash, obj)
        if isinstance(obj, dict):
            if len(obj) != 1:
                raise _ValueError("Object must have only one key", obj)

            for k, v in obj.items():
                if k == "Ref":
                    return _ForEachValueRef(_hash, v)
                if k == "Fn::FindInMap":
                    return _ForEachValueFnFindInMap(_hash, v)
                if k == "Fn::If":
                    return _ForEachValueFnIf(_hash, v)

        raise _TypeError(f"Unsupported value {obj!r}", obj)

    # pylint: disable=unused-argument
    def value(
        self, cfn, params: Mapping[str, Any] | None = None, only_params: bool = False
    ):
        return self._value

    @property
    def hash(self):
        return self._hash


class _FnFindInMapDefaultValue(_ForEachValue):
    def __init__(self, _hash: str, value: Any = None) -> None:
        super().__init__(_hash, value)
        if not isinstance(value, dict):
            raise _TypeError(
                "Fn::FindInMap parameter must be an object with key 'DefaultValue'",
                value,
